import{_ as o,o as t,c as a,a2 as l}from"./chunks/framework.Dhf_H6O0.js";const i="/mbit-mcpo-proxy-download/guide/images/local-rag-modal.png",p=JSON.parse('{"title":"Local Document Search (RAG)","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/local-rag.md","filePath":"catalog/local-rag.md"}'),n={name:"catalog/local-rag.md"};function r(s,e,d,h,c,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="local-document-search-rag" tabindex="-1">Local Document Search (RAG) <a class="header-anchor" href="#local-document-search-rag" aria-label="Permalink to &quot;Local Document Search (RAG)&quot;">​</a></h1><p>MCP Local RAG lets your AI tools search through your own documents — PDFs, Markdown, DOCX, HTML, and code files — without sending anything to the cloud. Everything runs locally on your Mac.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>You choose a folder on your Mac that contains your documents.</li><li>MCPBehindIT indexes those files using a local AI model (~90 MB, downloaded on first use).</li><li>Your AI tools can then search and retrieve content from those documents through the MCP gateway.</li></ol><p>All data stays on your machine: the index and the AI model are stored in the app data folder.</p><h2 id="step-1-add-from-catalog" tabindex="-1">Step 1: Add from catalog <a class="header-anchor" href="#step-1-add-from-catalog" aria-label="Permalink to &quot;Step 1: Add from catalog&quot;">​</a></h2><ol><li>Click <strong>Catalog</strong> in the sidebar.</li><li>Find <strong>MCP Local RAG</strong> (it has the <code>COMMUNITY</code> and <code>Local RAG</code> tags).</li><li>Click the <strong>+</strong> button.</li><li>A dialog opens:</li></ol><p><img src="'+i+'" alt="MCP Local RAG folder selection"></p><h2 id="step-2-choose-your-folder" tabindex="-1">Step 2: Choose your folder <a class="header-anchor" href="#step-2-choose-your-folder" aria-label="Permalink to &quot;Step 2: Choose your folder&quot;">​</a></h2><ol><li>Click <strong>Choose folder…</strong> and select the folder that contains the documents you want to search.</li><li>Only this folder (and its subfolders) will be indexed and searchable.</li><li>Click <strong>Add server</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">What files are supported?</p><ul><li>PDF</li><li>Markdown (.md)</li><li>DOCX (Microsoft Word)</li><li>HTML</li><li>Source code files</li></ul><p>Binary files, images, and video are not indexed.</p></div><h2 id="step-3-start-the-gateway" tabindex="-1">Step 3: Start the gateway <a class="header-anchor" href="#step-3-start-the-gateway" aria-label="Permalink to &quot;Step 3: Start the gateway&quot;">​</a></h2><ol><li>Go to <strong>Home</strong>.</li><li>Click <strong>Start</strong> (or <strong>Apply &amp; Restart</strong> if the gateway is already running).</li><li>On first use, the gateway downloads a small AI model (~90 MB). This happens once.</li></ol><h2 id="step-4-index-your-documents" tabindex="-1">Step 4: Index your documents <a class="header-anchor" href="#step-4-index-your-documents" aria-label="Permalink to &quot;Step 4: Index your documents&quot;">​</a></h2><ol><li>On the Dashboard, switch to the <strong>Documents</strong> tab.</li><li>You&#39;ll see a list of files from your selected folder.</li><li>Each file shows its indexing status: <ul><li><strong>Not indexed</strong> — the file hasn&#39;t been processed yet</li><li><strong>Indexed</strong> — the file is searchable</li></ul></li><li>Click <strong>Select not indexed</strong> to select all files that haven&#39;t been indexed yet.</li><li>Click <strong>Index selected</strong> to start indexing.</li><li>Wait for the indexing to complete. Large folders may take a few minutes.</li></ol><h2 id="step-5-search-in-your-ai-tool" tabindex="-1">Step 5: Search in your AI tool <a class="header-anchor" href="#step-5-search-in-your-ai-tool" aria-label="Permalink to &quot;Step 5: Search in your AI tool&quot;">​</a></h2><p>Once files are indexed, any AI tool connected to the gateway can use the <code>search_tools</code> function to find information in your documents.</p><p>For example, in Open WebUI you can ask:</p><blockquote><p>&quot;Search my documents for the latest quarterly report.&quot;</p></blockquote><p>The AI will use Local RAG to find and return relevant passages from your indexed files.</p><h2 id="managing-documents" tabindex="-1">Managing documents <a class="header-anchor" href="#managing-documents" aria-label="Permalink to &quot;Managing documents&quot;">​</a></h2><h3 id="refreshing-the-file-list" tabindex="-1">Refreshing the file list <a class="header-anchor" href="#refreshing-the-file-list" aria-label="Permalink to &quot;Refreshing the file list&quot;">​</a></h3><p>Click <strong>Refresh list</strong> on the Documents tab to rescan the folder. New files will appear as &quot;not indexed.&quot;</p><h3 id="re-indexing" tabindex="-1">Re-indexing <a class="header-anchor" href="#re-indexing" aria-label="Permalink to &quot;Re-indexing&quot;">​</a></h3><p>If you update a file, select it and click <strong>Index selected</strong> again to update the index.</p><h3 id="changing-the-folder" tabindex="-1">Changing the folder <a class="header-anchor" href="#changing-the-folder" aria-label="Permalink to &quot;Changing the folder&quot;">​</a></h3><p>To change which folder is indexed:</p><ol><li>Go to <strong>Servers</strong>, click <strong>Edit</strong> on the Local RAG server.</li><li>Update the document folder path.</li><li><strong>Apply &amp; Restart</strong> on Home.</li><li>Re-index the new folder.</li></ol><h2 id="advanced-cli-troubleshooting" tabindex="-1">Advanced: CLI &amp; troubleshooting <a class="header-anchor" href="#advanced-cli-troubleshooting" aria-label="Permalink to &quot;Advanced: CLI &amp; troubleshooting&quot;">​</a></h2><p>The Documents tab has a <strong>CLI &amp; advanced</strong> section (expand it at the bottom) with:</p><ul><li><strong>Status</strong> — shows the current state of the RAG engine</li><li><strong>Raw list</strong> — the complete file list from the CLI</li><li><strong>Ingest folder</strong> — manually trigger folder ingestion</li></ul><p>These tools are for power users and support troubleshooting. Normal usage doesn&#39;t require them.</p>',32)])])}const f=o(n,[["render",r]]);export{p as __pageData,f as default};
